const email = $('HTTP Request').item.json;
const ai = $json.output;

return [
  {
    json: {
      email_id: email.email_id,
      subject: email.subject,
      body: email.body,
      attachments: email.attachments,

      category: ai.category,
      confidence: ai.confidence
    }
  }
];

const items = $input.all();

return items.map(item => {
  const path = item.json.attachments;

  let type = "UNKNOWN";

  if (path.toLowerCase().includes("_si.")) {
    type = "SI";
  } else if (path.toLowerCase().includes("_bl.")) {
    type = "BL";
  }

  return {
    json: {
      email_id: item.json.email_id,
      attachment_path: path,
      document_type: type
    }
  };
});

const docs = $input.all();
const identified = $('Identify Attachment').all();

return docs.map((doc, index) => {
  return {
    json: {
      email_id: identified[index].json.email_id,
      document_type: identified[index].json.document_type,
      attachment_path: identified[index].json.attachment_path,
      document_text: doc.json.data
    }
  };
});

const extracted = $input.all();
const sourceDocs = $('Prepare Document').all();

const docs = {};

for (let i = 0; i < extracted.length; i++) {
  const type = sourceDocs[i].json.document_type;
  const data = extracted[i].json.output ?? extracted[i].json;

  docs[type] = data;
}

const si = docs.SI;
const bl = docs.BL;

if (!si || !bl) {
  return [{
    json: {
      status: "NEEDS_REVIEW",
      review_reason: "missing_attachment",
      has_defect: false,
      defect_fields: []
    }
  }];
}

const fields = [
  "shipper",
  "consignee",
  "notify_party",
  "port_of_loading",
  "port_of_discharge",
  "container_count",
  "gross_weight_kg"
];

function normalizeText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .trim()
    .toUpperCase()
    .replace(/\s+/g, " ")
    .replace(/[.,]/g, "");
}

const defectFields = [];

for (const field of fields) {

  let siValue = si[field];
  let blValue = bl[field];

  if (field === "container_count" || field === "gross_weight_kg") {
    if (Number(siValue) !== Number(blValue)) {
      defectFields.push(field);
    }
  } else {
    if (normalizeText(siValue) !== normalizeText(blValue)) {
      defectFields.push(field);
    }
  }
}

const hasDefect = defectFields.length > 0;

return [{
  json: {
    status: hasDefect ? "MISMATCH" : "OK",
    review_reason: null,
    has_defect: hasDefect,
    defect_fields: defectFields,

    si_extracted: si,
    bl_extracted: bl
  }
}];

const items = $input.all();
const results = {};

for (const item of items) {
  const data = item.json;
  const emailId = data.email_id;

  if (!emailId) continue;

  let category = data.category || "GENERAL";
  let status = data.status || "OK";
  let reviewReason = data.review_reason || null;
  let hasDefect = data.has_defect || false;
  let defectFields = data.defect_fields || [];

  if (category !== "BL_COMPARISON") {
    status = "OK";
    reviewReason = null;
    hasDefect = false;
    defectFields = [];
  }

  results[emailId] = {
    category: category,
    status: status,
    review_reason: reviewReason,
    has_defect: hasDefect,
    defect_fields: defectFields
  };
}

return [{
  json: results
}];

const email = $('HTTP Request').item.json;

return {
  json: {
    email_id: email.email_id,
    category: $json.output.category,
    status: "OK",
    review_reason: null,
    has_defect: false,
    defect_fields: []
  }
};

const email = $('HTTP Request').item.json;

return {
  json: {
    email_id: email.email_id,
    category: "BL_COMPARISON",
    status: "NEEDS_REVIEW",
    review_reason: "missing_attachment",
    has_defect: false,
    defect_fields: []
  }
};
